def lawvere_witness(phi, n, f):
    d = lambda x: f(phi(x, x))
    d_tuple = tuple(d(x) for x in range(n))
    for a in range(n):
        if tuple(phi(a, x) for x in range(n)) == d_tuple:
            return phi(a, a)
    return -1

from math import comb
def reflective_deficiency(n):
    return sum((-1)**k * comb(n, k) * n**(n-k) for k in range(n+1))

def observation_quotient(f, n):
    classes = {}
    for x in range(n):
        key = f(x)
        classes.setdefault(key, set()).add(x)
    return classes
